"""Artifact transport tests: generated bytes only, no scientific fitting."""
import hashlib
import json
import zipfile

import pytest

from scripts import runtime_bundle as bundle


def data_fixture(path):
    for name in bundle.REQUIRED | bundle.VALIDATION:
        target = path / name
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(b'fixture artifact')
    (path / 'validation/harmonization.json').write_text(json.dumps({'metrics': {'data_mode': 'real'}}))
    (path / 'validation/qa.json').write_text(json.dumps({'metrics': {'checks': [{'result': 'pass'}]}}))


def test_package_is_deterministic_and_round_trips(tmp_path):
    data = tmp_path / 'source'
    data_fixture(data)
    (data / 'private.env').write_text('excluded')
    digest = bundle.pack(data, tmp_path / 'a.zip')
    assert digest == bundle.pack(data, tmp_path / 'b.zip')
    bundle.unpack(tmp_path / 'a.zip', tmp_path / 'result', digest)
    assert (tmp_path / 'result/cells.parquet').read_bytes() == b'fixture artifact'
    assert not (tmp_path / 'result/private.env').exists()
    with pytest.raises(ValueError, match='overwrite'):
        bundle.unpack(tmp_path / 'a.zip', tmp_path / 'result', digest)


def test_rejects_unverified_or_synthetic_outputs(tmp_path):
    data_fixture(tmp_path / 'data')
    (tmp_path / 'data/validation/harmonization.json').write_text('{"metrics":{"data_mode":"synthetic"}}')
    with pytest.raises(ValueError, match='real-data'):
        bundle.pack(tmp_path / 'data', tmp_path / 'runtime.zip')


def test_rejects_corruption_and_unexpected_paths(tmp_path):
    archive = tmp_path / 'bad.zip'
    archive.write_bytes(b'corrupt')
    with pytest.raises(ValueError, match='SHA256'):
        bundle.unpack(archive, tmp_path / 'out', '0' * 64)
    with zipfile.ZipFile(archive, 'w') as package:
        package.writestr('../outside.txt', 'not allowed')
    with pytest.raises(ValueError, match='unexpected'):
        bundle.unpack(archive, tmp_path / 'out', hashlib.sha256(archive.read_bytes()).hexdigest())
    assert not (tmp_path / 'outside.txt').exists()
